function extraCategory(text){
 const s=String(text||"");
 for(const [cat,re] of EXTRA_CATEGORY_RULES)if(re.test(s))return cat;
 return "その他";
}

const CATEGORY_LABELS={
 character:"作品",
 relationship:"関係性カテゴリ",
 situation:"シチュカテゴリ",
 mood:"雰囲気カテゴリ",
 extra:"追加条件カテゴリ"
};
function categoryOrderFor(key){
 if(key==="character"){
   return unique(baseFilteredCharacters().map(c=>c.work||"作品未設定"));
 }
 if(key==="relationship")return RELATIONSHIP_CATEGORY_ORDER;
 if(key==="situation")return SITUATION_CATEGORY_ORDER;
 if(key==="mood")return MOOD_CATEGORY_ORDER;
 if(key==="extra")return EXTRA_CATEGORY_ORDER;
 return [];
}
function categoryFor(key,value){
 if(key==="character"){
   const c=typeof value==="string"?state.characters.find(c=>c.id===value):value;
   return c?.work||"作品未設定";
 }
 if(key==="relationship")return relationshipCategory(value);
 if(key==="situation")return situationCategory(value);
 if(key==="mood")return moodCategory(value);
 if(key==="extra")return extraCategory(value);
 return "その他";
}
function categoryPass(key,value){
 const cat=categoryFor(key,value);
 const include=state.categoryInclude[key]||null;
 const excluded=state.categoryExcluded[key]||new Set();
 if(include&&cat!==include)return false;
 if(excluded.has(cat))return false;
 return true;
}
function categoryCounts(key){
 const order=categoryOrderFor(key),m=new Map(order.map(c=>[c,0]));
 const src=key==="character"?baseFilteredCharacters():(state.pools[key]||[]);
 for(const v of src){const c=categoryFor(key,v);m.set(c,(m.get(c)||0)+1)}
 return m;
}
function setCategoryInclude(key,cat){
 if(!Object.prototype.hasOwnProperty.call(state.categoryInclude,key))return;
 if(state.categoryInclude[key]===cat)state.categoryInclude[key]=null;
 else{
   state.categoryInclude[key]=cat;
   state.categoryExcluded[key].delete(cat);
 }
 save();renderChooserCategoryChips();renderChooserList();updateCategoryStatus(key);
 if(key==="character"){renderGachaFilters();renderManager()}
}
function toggleCategoryExclude(key,cat){
 if(!state.categoryExcluded[key])return;
 if(state.categoryExcluded[key].has(cat))state.categoryExcluded[key].delete(cat);
 else{
   state.categoryExcluded[key].add(cat);
   if(state.categoryInclude[key]===cat)state.categoryInclude[key]=null;
 }
 save();renderChooserCategoryChips();renderChooserList();updateCategoryStatus(key);
 if(key==="character"){renderGachaFilters();renderManager()}
}
function clearCategoryRules(key){
 state.categoryInclude[key]=null;state.categoryExcluded[key].clear();
 save();renderChooserCategoryChips();renderChooserList();updateCategoryStatus(key);
 if(key==="character"){renderGachaFilters();renderManager()}
}


