const CANONICAL_TAGS={"age":["年上系","年下系","同年代系"],"personality":["優しい","誠実","冷静","現実的","知的","明るい","情熱的","不器用","寡黙","自信家","強気","マイペース","策士","包容力","一途","危険","荒っぽい","気弱","素直","個性的","挑発的","負けず嫌い","野心家","キザ","女好き"],"appearance":["美形","色気","体格がいい","強面"],"role":["主人公","悪役","ライバル","指導者","戦闘系","知識職","職人系","権力者","一般人"]};
const CANONICAL_TAG_SET=new Set(Object.values(CANONICAL_TAGS).flat());
const TAG_GROUP_ORDER=["age","personality","appearance","role"];
const TAG_GROUP_LABELS={
 age:"年齢・距離感",personality:"性格・雰囲気",appearance:"容姿・体格",role:"役割・属性"
};
const AGE_TAGS=new Set(CANONICAL_TAGS.age);
const APPEARANCE_TAGS=new Set(CANONICAL_TAGS.appearance);
const ROLE_TAGS=new Set(CANONICAL_TAGS.role);

function tagGroupOf(tag){
 if(AGE_TAGS.has(tag))return "age";
 if(APPEARANCE_TAGS.has(tag))return "appearance";
 if(ROLE_TAGS.has(tag))return "role";
 return "personality";
}
function orderedSeries(work,values){
 const arr=[...new Set(values.filter(Boolean))];
 const order=WORK_SERIES_ORDER[work]||[];
 return arr.sort((a,b)=>{
   const ia=order.indexOf(a),ib=order.indexOf(b);
   if(ia!==-1||ib!==-1){
     if(ia===-1)return 1;if(ib===-1)return -1;
     return ia-ib;
   }
   if(work==="ジョジョの奇妙な冒険"){
     const ma=String(a).match(/^(\d+)部/),mb=String(b).match(/^(\d+)部/);
     if(ma&&mb&&Number(ma[1])!==Number(mb[1]))return Number(ma[1])-Number(mb[1]);
   }
   return String(a).localeCompare(String(b),"ja",{numeric:true});
 });
}

